package com.arjunren.coop;import org.junit.jupiter.api.*;import java.math.*;import static org.junit.jupiter.api.Assertions.*;
class AccountServiceTest{Database db;AccountService s;@BeforeEach void init()throws Exception{db=new Database("jdbc:h2:mem:"+System.nanoTime()+";DB_CLOSE_DELAY=-1");db.migrate();try(var c=db.connection()){c.createStatement().execute("INSERT INTO members(member_number,full_name,email) VALUES('M','Member','m@x.com')");c.createStatement().execute("INSERT INTO accounts(member_id,balance) VALUES(1,100)");c.createStatement().execute("INSERT INTO users(username,password_hash,role) VALUES('u','x','TELLER')");}s=new AccountService(db);}@Test void depositUpdatesBalance(){assertEquals(new BigDecimal("125.00"),s.move(1,"DEPOSIT",new BigDecimal("25"),"R1",1).balance());}@Test void withdrawalUpdatesBalance(){assertEquals(new BigDecimal("60.00"),s.move(1,"WITHDRAWAL",new BigDecimal("40"),"R2",1).balance());}@Test void rejectsOverdraft(){assertThrows(IllegalStateException.class,()->s.move(1,"WITHDRAWAL",new BigDecimal("101"),"R3",1));}@Test void rejectsDuplicateReference(){s.move(1,"DEPOSIT",BigDecimal.ONE,"R4",1);assertThrows(IllegalStateException.class,()->s.move(1,"DEPOSIT",BigDecimal.ONE,"R4",1));}}
